create or replace function public.submit_zuno_caos_result(p_score integer, p_won boolean, p_rounds integer) returns table(game_xp integer, game_level integer) language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); xp_gain integer; new_xp integer; new_level integer; begin if uid is null then raise exception 'not_authenticated'; end if; if p_score<0 or p_score>3000 or p_rounds<1 or p_rounds>20 then raise exception 'invalid_result'; end if; xp_gain:=least(220, 30 + floor(p_score/30)::int + case when p_won then 60 else 0 end); insert into public.game_scores(user_id,game,score,correct_answers,questions) values(uid,'zuno_caos',p_score,case when p_won then 1 else 0 end,p_rounds); insert into public.game_progress(user_id,xp,level,total_games,wins,total_correct,best_score,solo_games,multiplayer_games,multiplayer_wins) values(uid,xp_gain,1,1,case when p_won then 1 else 0 end,0,p_score,0,1,case when p_won then 1 else 0 end) on conflict(user_id) do update set xp=public.game_progress.xp+xp_gain,total_games=public.game_progress.total_games+1,wins=public.game_progress.wins+case when p_won then 1 else 0 end,best_score=greatest(public.game_progress.best_score,p_score),multiplayer_games=public.game_progress.multiplayer_games+1,multiplayer_wins=public.game_progress.multiplayer_wins+case when p_won then 1 else 0 end,updated_at=now(); select xp into new_xp from public.game_progress where user_id=uid; new_level:=greatest(1,1+floor(sqrt(new_xp/250.0))::int); update public.game_progress set level=new_level where user_id=uid; return query select new_xp,new_level; end $$; revoke all on function public.submit_zuno_caos_result(integer,boolean,integer) from public,anon; grant execute on function public.submit_zuno_caos_result(integer,boolean,integer) to authenticated;
